use super::*;

/// Is this record a COHESIVE module (leave whole) rather than a genuine independent-leaf collection?
/// Returns `Some(reason)` to DEMOTE it off the decomposition worklist. CONSERVATIVE by design: a strong
/// cohesion signal demotes, because a false "decompose" FRAGMENTS a cohesive module (Decision 3) — the
/// harmful direction. Two signals, both a FRACTION of the leaves: (1) PRIVATE-parent-item references —
/// the SHARPEST discriminator (validated against 10 ground-truth cases): a leaf leaning on a private
/// helper/type that stays behind is entangled, because extracting it needs an explicit `use super::<priv>`
/// (a glob re-exports only pub items); (2) module-own-type coupling of leaf SIGNATURES — methods-in-
/// disguise. A serde-json fraction was tried and REJECTED: it demotes genuine collections that merely
/// parse JSON (patterns/closure/backing), so JSON use is not cohesion. Inter-leaf calls are also not a
/// signal: node_urn's grammar leaves call each other and are still a genuine collection worth splitting.
/// Two known limits it cannot see (semantic cohesion, zero mechanical coupling): preview-props, crossgraph
/// — a human decomposer skips those on read, which the propose-only worklist expects.
pub(crate) fn cohesion_reason(code: &str, tech: &str, leaf_names: &[String]) -> Option<String> {
    let n = leaf_names.len();
    if n < 2 {
        return None;
    }
    let lang = language_for(tech)?;
    let mut parser = Parser::new();
    parser.set_language(&lang).ok()?;
    let tree = parser.parse(code, None)?;
    let src = code.as_bytes();
    let root = tree.root_node();
    let types = module_defined_types(root, src);
    let want: std::collections::HashSet<&str> = leaf_names.iter().map(String::as_str).collect();

    // Private parent items that are NOT themselves extractable leaves — a private TYPE, or a private
    // helper that is impure/stateful. These are genuine parent complexity that stays behind; a leaf
    // reaching one is entangled (it needs explicit `use super::<priv>`, and the item cannot travel as a
    // clean pub child). A private item that is ITSELF a pure leaf is excluded: it extracts alongside the
    // others, so a caller referencing it is an inter-leaf call, not coupling — the same shape as
    // node_urn's grammar. (Measured: this separates the coupled-cohesive cases; the purely-semantic ones,
    // exports/preview-props/crossgraph — pure-fn collections a human judged cohesive — are mechanically
    // indistinguishable from a genuine collection and stay on the propose-only worklist for the read.)
    let private_nonleaf: std::collections::HashSet<String> =
        private_item_names(root, src).into_iter().filter(|nm| !want.contains(nm.as_str())).collect();

    let (mut coupled_leaves, mut entangled_leaves) = (0usize, 0usize);
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if child.kind() != "function_item" {
            continue;
        }
        let Some(name) = fn_name(child, src) else { continue };
        if !want.contains(name.as_str()) {
            continue;
        }
        let text = child.utf8_text(src).unwrap_or("");
        // (1) references a PRIVATE parent item that stays behind — entangled.
        if body_references_private(text, &name, &private_nonleaf) {
            entangled_leaves += 1;
        }
        // (2) signature names the module's own struct/enum — a method-in-disguise.
        let sig = leaf_signature(child, src);
        if types.iter().any(|t| !t.is_empty() && sig.contains(t.as_str())) {
            coupled_leaves += 1;
        }
    }
    let nf = n as f64;
    // private-coupled: the primary signal. Even a modest fraction of leaves reaching into private parent
    // state means the module is entangled — 0.15 sits above the incidental single-helper case (motion is
    // 1/13 = 0.08) and below the cohesive shape (usage 1/5 = 0.20, exports 6/13, similarity 28/43).
    if entangled_leaves as f64 / nf >= 0.15 {
        return Some(format!("private-coupled: {entangled_leaves}/{n} leaves reference a private parent item"));
    }
    // type-coupled: a strong majority of leaf signatures name the module's own types (0.7 clears node_urn
    // at 0.6, which returns its own small parse structs yet is a genuine grammar collection).
    if coupled_leaves >= 2 && coupled_leaves as f64 / nf >= 0.7 {
        return Some(format!("type-coupled: {coupled_leaves}/{n} leaves operate on the module's own types"));
    }
    None
}
